param(
    [switch]$SkipPilotPreparation
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$ProjectRoot = (Get-Location).Path
$PackagePath = Join-Path $ProjectRoot "package.json"
if (-not (Test-Path $PackagePath -PathType Leaf)) {
    throw "Run this installer from the EMETSEES project root containing package.json."
}

$CompilerPath = Join-Path $ProjectRoot "scripts\entity\build-cached-emet-explanations.js"
$BatchCompilerPath = Join-Path $ProjectRoot "scripts\entity\batch-cached-emet-explanations.js"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot ".private\entity\backups\P04-batch-v1.2-$Timestamp"
New-Item -ItemType Directory -Force -Path $BackupRoot | Out-Null

$Targets = @(
    [pscustomobject]@{ Path = $CompilerPath; Name = "build-cached-emet-explanations.js" },
    [pscustomobject]@{ Path = $BatchCompilerPath; Name = "batch-cached-emet-explanations.js" },
    [pscustomobject]@{ Path = $PackagePath; Name = "package.json" }
)

$BackupEntries = @()
foreach ($Target in $Targets) {
    $Existed = Test-Path $Target.Path -PathType Leaf
    $BackupPath = Join-Path $BackupRoot $Target.Name
    if ($Existed) {
        Copy-Item -LiteralPath $Target.Path -Destination $BackupPath -Force
    }
    $BackupEntries += [pscustomobject]@{
        Path = $Target.Path
        BackupPath = $BackupPath
        Existed = $Existed
    }
}

function Write-Base64Utf8File {
    param(
        [Parameter(Mandatory = $true)][string]$Destination,
        [Parameter(Mandatory = $true)][string]$Payload
    )
    $Parent = Split-Path -Parent $Destination
    New-Item -ItemType Directory -Force -Path $Parent | Out-Null
    [System.IO.File]::WriteAllBytes($Destination, [Convert]::FromBase64String($Payload))
}

$CompilerPayload = ""
$BatchCompilerPayload = ""
$PackageUpdaterPayload = ""
$PackageUpdaterPath = Join-Path $BackupRoot "update-package-scripts.js"

try {
    Write-Host ""
    Write-Host "Installing P04 OpenAI Batch support v1.2.0..." -ForegroundColor Cyan

    Write-Base64Utf8File -Destination $CompilerPath -Payload $CompilerPayload
    Write-Base64Utf8File -Destination $BatchCompilerPath -Payload $BatchCompilerPayload
    Write-Base64Utf8File -Destination $PackageUpdaterPath -Payload $PackageUpdaterPayload

    & node --check $CompilerPath
    if ($LASTEXITCODE -ne 0) { throw "P04 compiler syntax validation failed." }
    & node --check $BatchCompilerPath
    if ($LASTEXITCODE -ne 0) { throw "P04 Batch compiler syntax validation failed." }
    & node $PackageUpdaterPath
    if ($LASTEXITCODE -ne 0) { throw "package.json integration failed." }

    & npm run plan:cached-emet
    if ($LASTEXITCODE -ne 0) { throw "Existing P04 cache compatibility check failed." }

    if (-not $SkipPilotPreparation) {
        Write-Host ""
        Write-Host "Preparing a no-cost 24-entity Batch API pilot..." -ForegroundColor Cyan
        & npm run prepare:cached-emet-batch -- --sample-per-corpus 8 --request-size 4
        if ($LASTEXITCODE -ne 0) { throw "Pilot Batch preparation failed." }
        & npm run verify:cached-emet-batch
        if ($LASTEXITCODE -ne 0) { throw "Pilot Batch verification failed." }
    }

    Write-Host ""
    Write-Host "P04 OpenAI Batch support installed successfully." -ForegroundColor Green
    Write-Host "Backup: $BackupRoot"
    Write-Host ""
    if (-not $SkipPilotPreparation) {
        Write-Host "The pilot is prepared but has NOT been submitted."
        Write-Host "Next command:"
        Write-Host "npm run submit:cached-emet-batch"
    }
    else {
        Write-Host "Prepare a pilot with:"
        Write-Host "npm run prepare:cached-emet-batch -- --sample-per-corpus 8 --request-size 4"
    }
}
catch {
    Write-Host ""
    Write-Host "Installation failed. Restoring the previous files..." -ForegroundColor Yellow
    foreach ($Entry in $BackupEntries) {
        if ($Entry.Existed) {
            $Parent = Split-Path -Parent $Entry.Path
            New-Item -ItemType Directory -Force -Path $Parent | Out-Null
            Copy-Item -LiteralPath $Entry.BackupPath -Destination $Entry.Path -Force
        }
        elseif (Test-Path $Entry.Path) {
            Remove-Item -LiteralPath $Entry.Path -Force
        }
    }
    throw
}
